// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // A non-owner calls transferOwnership to change the owner
        address nonOwner = address(0x123);
        vm.prank(nonOwner);
        c.transferOwnership(address(1));
        // Now the owner is address(1), and nonOwner calls owned()
        vm.prank(nonOwner);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Reference: owned() reverts because nonOwner != owner (onlyOwner modifier)
        // Bug: owned() succeeds because modifier was removed
        assertTrue(ok == false);
    }
}

