pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initially owner is address(0)
        address nonOwner = address(1);
        vm.prank(nonOwner);
        c.transferOwnership(address(0)); // non-owner sets owner to address(0)

        // Now try owned() as nonOwner; reference reverts (onlyOwner blocks non-owner), buggy version does not revert
        bool ok;
        vm.prank(nonOwner);
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok); // Reference: reverts → ok = false → assert fails; Bug: succeeds → ok = true → assert passes
    }
}

